import sys

s = sys.stdin.read().strip()
if not s:
    print(0)
else:
    prod = 1
    found = False
    for ch in s:
        if ch.isdigit():
            d = int(ch)
            if d % 2 == 1:
                prod *= d
                found = True
    print(prod if found else 0)

import sys

s = sys.stdin.read()
out = []
vowels = set('aeiouAEIOU')

for ch in s:
    if ch.isalpha():
        c = ch.swapcase()
    else:
        c = ch
    if c in vowels:
        c = chr(ord(c) + 2)
    out.append(c)

sys.stdout.write(''.join(out))

