import sys

tokens = sys.stdin.read().split()
total = 0

for s in tokens:
    if '.' in s:
        continue
    try:
        n = int(s)
    except ValueError:
        continue
    if n > 0 and n % 2 == 1:
        total += n * n

print(total)

