n = int(input().strip())
isprime = [True] * (n + 1)
isprime[0] = isprime[1] = False
ans = []
for i in range(2, n):
    if isprime[i]:
        ans.append(i)
        for j in range(i * 2, n, i):
            isprime[j] = False
print(ans)

def largest_divisor(n):
    for i in range(2, n):
        if n % i == 0:
            return n // i
    return 1
